from usg.dsl import *

# Find a signalised crossing to use
crossings = MAP.crossings(control="signals")
if not crossings:
    crossings = MAP.crossings()
cr = sorted(crossings, key=lambda c: (MAP.road(c["road"])["oneway"], -MAP.road(c["road"])["lanes"], -MAP.road(c["road"])["length"]))[0]
cid, road, s = cr["id"], cr["road"], cr["road_s"]
length = MAP.road(road)["length"]

# Ensure we use crossing_1 as per spec
if cid != "crossing_1":
    # Find crossing_1 specifically
    all_crossings = MAP.crossings()
    for c in all_crossings:
        if c["id"] == "crossing_1":
            cid, road, s = c["id"], c["road"], c["road_s"]
            length = MAP.road(road)["length"]
            break

scenario = ScenarioBuilder("cross_with_traffic", MAP, scenario_type="dyn_nav",
                           description="Cross on green while avoiding a car.")
scenario.user(MAP.crossing_side(cid, "start", inset=2.0))

# Create the signal cycle for crossing_1
signal_name = scenario.signal_cycle("crossing_1", green=15, red=20, initial="red")

# Create the vehicle
route = MAP.drive_route(road, max(0.0, s - 30.0), min(length, s + 30.0), "forward")
scenario.vehicle("Car1", route[0], route[1:], speed=8.0, model="car_white", start_when=when_task_starts(None))

handles = scenario.apply_spec({
    "tasks": [{
        "name": "cross_with_traffic",
        "instruction": "Wait for green, then cross while avoiding the car.",
        "goal": {
            "op": "call",
            "name": "cross",
            "args": {
                "far_zone": {
                    "kind": "crossing_side",
                    "id": "crossing_1",
                    "side": "end",
                    "inset": 1.0,
                    "r": 1.5
                }
            }
        },
        "safety": [
            {
                "op": "call",
                "name": "collision_free",
                "args": {
                    "entity": "Car1",
                    "r": 0.3
                }
            },
            {
                "op": "call",
                "name": "obey_signal",
                "args": {
                    "zone": {
                        "kind": "crossing",
                        "id": "crossing_1"
                    },
                    "signal": "signal_1"
                }
            }
        ],
        "timeout": {
            "initial": 60,
            "baseline": 90
        }
    }]
})

