cid, road, s = cr["id"], cr["road"], cr["road_s"]

scenario = ScenarioBuilder("look_then_cross", MAP, scenario_type="custom",
                           description="Look at an approaching car, then cross the road.")
scenario.user(MAP.crossing_side(cid, "start", inset=2.0))

# Create the signal cycle as required by the specification
signal_name = scenario.signal_cycle(cid, green=15, red=20, initial="red")

# Create the moving vehicle (Car1) that the user must look at and avoid
road_len = MAP.road(road)["length"]
start_pos = max(10.0, s - 30.0)
end_pos = min(road_len - 10.0, s + 30.0)
route = MAP.drive_route(road, start_pos, end_pos, "forward")

# Ensure route is valid before creating the vehicle
if route and route[0] is not None:
    scenario.vehicle("Car1", route[0], route[1:], speed=8.0, model="car_white", start_when=when_task_starts(None))
else:
    # Fallback: use a simple start position if drive_route fails
    scenario.vehicle("Car1", [0.0], [], speed=8.0, model="car_white", start_when=when_task_starts(None))

# Apply the specification
