from usg.dsl import *

# Find the bus stop and its road
bus_stop = MAP.bus_stops()[0]
dest = MAP.place(bus_stop["id"])
road = MAP.road(bus_stop["road"])
side = MAP.side_of_road(dest)
start = MAP.sidewalk_at(road, side, max(6.0, MAP.road_s_of(dest) - 40.0))

# Create parked vehicles along the road (to be avoided)
slot1 = MAP.kerb_slots(road, "right", spacing=7)[0]
slot2 = MAP.kerb_slots(road, "right", spacing=7)[1]
scenario.parked_vehicle("parked_1", slot1)
scenario.parked_vehicle("parked_2", slot2)

# Create a simple route for the vehicles to ensure they are on the road
route1 = MAP.drive_route(road, MAP.road_s_of(dest) - 100, MAP.road_s_of(dest) + 50, "forward")
route2 = MAP.drive_route(road, MAP.road_s_of(dest) - 100, MAP.road_s_of(dest) + 50, "forward")

SPEC = {
    "tasks": [
        {
            "name": "avoid_parked",
            "instruction": "Avoid the parked vehicles while walking to the bus stop.",
            "goal": {
                "op": "call",
                "name": "reach",
                "args": {
                    "zone": {
                        "kind": "feature",
                        "id": "bus_stop_2",
                        "r": 3
                    }
                }
            },
            "safety": [
                {
                    "op": "call",
                    "name": "collision_free",
                    "args": {
                        "entity": "parked_1",
                        "r": 0.5
                    }
                },
                {
                    "op": "call",
                    "name": "collision_free",
                    "args": {
                        "entity": "parked_2",
                        "r": 0.5
                    }
                }
            ],
            "timeout": {
                "initial": 90,
                "baseline": 135
            }
        }
    ]
}

scenario = ScenarioBuilder("avoid_parked", MAP, scenario_type="custom", description="Avoid parked vehicles while walking to the bus stop.")
scenario.user(start.facing(dest))
scenario.vehicle("Car1", MAP.lane_center(road, MAP.road_s_of(dest) - 50, "forward"), route=route1, speed=8, model="car_red")
scenario.vehicle("Car2", MAP.lane_center(road, MAP.road_s_of(dest) + 50, "forward"), route=route2, speed=8, model="car_blue")
handles = scenario.apply_spec(SPEC)

